import Product from './Product.js';
import images from '../../assets/images/product1.png';
import '../../Components/css/ProductList.css';
export default function ProductsList() {
  const products = [
    { id: 1, name: 'Product 1', price: 100, description: 'This is product 1', img_src: images, dimensions: { width: 200, height: 200 } },
    { id: 2, name: 'Product 2', price: 200, description: 'This is product 2', img_src: images, dimensions: { width: 200, height: 200 } },
    { id: 3, name: 'Product 3', price: 300, description: 'This is product 3', img_src: images, dimensions: { width: 200, height: 200 } },
    { id: 4, name: 'Product 4', price: 400, description: 'This is product 4', img_src: images, dimensions: { width: 200, height: 200 } },
    { id: 5, name: 'Product 5', price: 500, description: 'This is product 5', img_src: images, dimensions: { width: 200, height: 200 } },
    { id: 6, name: 'Product 6', price: 600, description: 'This is product 6', img_src: images, dimensions: { width: 200, height: 200 } },
  ];
  return (
    <div className="productsPageContainer">
      <h1>Products List</h1>
      <span className="productsList">
        {products.map(product => (
          <Product key={product.id} {...product} />
        ))}
      </span>
    </div>
  );
}
